import {constructionProjects,constructionParts,constructionPalette,buildFixed} from './construction.js';
export function renderConstructionControls({root,state,onCell,onAction,onPart}){const focused=document.activeElement?.dataset?.buildCell;root.replaceChildren();root.hidden=!state.active&&!state.orbit;if(root.hidden)return;const add=(parent,label,fn)=>{const b=document.createElement('button');b.textContent=label;b.onclick=fn;parent.append(b);return b};const toolbar=document.createElement('div');toolbar.className='build-toolbar';root.append(toolbar);if(state.orbit){add(toolbar,'← Home Base',()=>onAction('exit'));add(toolbar,'🔊 Listen',()=>onAction('listen'));return;}for(const [id,label]of [['test','▶ Test model'],['undo','↶ Undo'],['reset','↺ Reset'],['hint','✨ Plan'],['robot','🤖 Robot build'],['exit','← Yard']])add(toolbar,label,()=>onAction(id));const grid=document.createElement('div');grid.className='build-grid';grid.setAttribute('role','group');grid.setAttribute('aria-label',constructionProjects[state.active].name+' placement grid');root.append(grid);
for(let y=0;y<5;y++)for(let x=0;x<12;x++){const c=state.boards[state.active]?.[y*12+x],fixed=buildFixed(state.active,x,y),b=add(grid,'',()=>onCell(x,y));b.dataset.buildCell=x+','+y;b.setAttribute('aria-label','Column '+(x+1)+', row '+(y+1)+': '+(fixed?'fixed support':c?.part||'empty'));b.disabled=fixed;}
const palette=document.createElement('div');palette.className='build-palette';palette.setAttribute('role','group');palette.setAttribute('aria-label','Prefabricated parts');root.append(palette);for(const id of constructionPalette(state.active)){const part=constructionParts.find(p=>p[0]===id),b=add(palette,part[2]+' '+part[1],()=>onPart(id));b.dataset.buildPart=id;b.setAttribute('aria-pressed',String(state.selected===id));}if(state.active==='pipes'||state.active==='water')add(palette,'↻ Rotate next part',()=>onAction('rotate'));if(state.active==='power')add(palette,'⚡ Source '+(state.power?'ON':'OFF'),()=>onAction('power'));add(palette,'📦 My parts',()=>onAction('parts'));const note=document.createElement('p');note.className='build-instruction';note.textContent=state.selected+': tap a cell to place. Tap the same block to remove; tap a pipe to rotate.';root.append(note);if(focused)root.querySelector('[data-build-cell="'+focused+'"]')?.focus();}
